#pragma once
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* Recognise only a pristine, empty SPIFFS image with 256-byte pages and
 * 4096-byte blocks. Every byte must be FF except the exact per-block magic
 * generated by SPIFFS_USE_MAGIC_LENGTH. No filename, lookup entry, data page,
 * erase counter or other unknown byte may be discarded. A shorter pristine
 * image followed by erased flash is accepted; damaged/mixed images are not. */
typedef struct {
    size_t partition_blocks;
    size_t image_blocks;
    size_t blocks_checked;
    bool valid;
} tp_empty_spiffs_t;

static inline void tp_empty_spiffs_begin(tp_empty_spiffs_t *scan,size_t bytes)
{
    *scan=(tp_empty_spiffs_t){.partition_blocks=bytes/4096,
        .valid=bytes>=3*4096&&bytes%4096==0&&bytes/4096<=32767};
}

static inline void tp_empty_spiffs_block(tp_empty_spiffs_t *scan,const uint8_t *block,size_t bytes)
{
    if(!scan->valid)return;
    size_t index=scan->blocks_checked;
    if(bytes!=4096||index>=scan->partition_blocks){scan->valid=false;return;}
    if(!index){
        uint16_t magic=(uint16_t)block[252]|((uint16_t)block[253]<<8);
        scan->image_blocks=magic^(uint16_t)(0x20140529U^256U);
        if(scan->image_blocks<3||scan->image_blocks>scan->partition_blocks){scan->valid=false;return;}
    }
    uint16_t magic=(uint16_t)(0x20140529U^256U^(scan->image_blocks-index));
    for(size_t i=0;i<bytes;i++){
        uint8_t expected=0xff;
        if(index<scan->image_blocks&&i==252)expected=(uint8_t)magic;
        if(index<scan->image_blocks&&i==253)expected=(uint8_t)(magic>>8);
        if(block[i]!=expected){scan->valid=false;return;}
    }
    ++scan->blocks_checked;
}

static inline bool tp_empty_spiffs_complete(const tp_empty_spiffs_t *scan)
{
    return scan->valid&&scan->blocks_checked==scan->partition_blocks;
}
